import {
  ServerInterface,
  ServerInterfaceCallbacks,
} from "sock-server/server-interface/ServerInterface";
import { SockServer } from "sock-server/SockServer";

export class MockServerInterface implements ServerInterface {
  sockServer: SockServer;
  callbacks?: ServerInterfaceCallbacks;
  connId?: string;
  handleMsg: (msg: string) => void;
  disconnect: (isIntentionalShutdown?: boolean) => void;
  isClosed: boolean;

  constructor(sockServer: SockServer, connId?: string) {
    this.sockServer = sockServer;
    this.connId = connId;
    this.handleMsg = (msg) => {
      throw new Error("connection not initialized yet");
    };
    this.disconnect = () => {
      throw new Error("connection not initialized yet");
    };
    this.isClosed = false;
  }

  init(callbacks: ServerInterfaceCallbacks) {
    this.callbacks = callbacks;
    this.connect();
  }

  private connect(): void {
    if (this.callbacks === undefined)
      throw new Error("expect callbacks to be defined");
    const { onOpen, onResp, afterDisconnect } = this.callbacks;
    const { handleMsg, removeClient } = this.sockServer.addClient(
      {
        send: (msg) => {
          if (this.isClosed) return;
          Promise.resolve()
            .then(() => {
              onResp(msg);
            })
            .catch(console.error);
        },
        close: () => {
          this.close();
        },
      },
      this.connId
    );
    this.handleMsg = handleMsg;
    this.disconnect = (isIntentionalShutdown = false) => {
      removeClient();
      afterDisconnect({
        numReconnections: 0,
        reconnectDelayInSeconds: 0,
        isIntentionalShutdown,
      });
    };

    onOpen();
  }

  send(msg: string) {
    if (this.isClosed) return;
    Promise.resolve()
      .then(() => {
        if (this.isClosed) return;
        this.handleMsg(msg);
      })
      .catch(console.error);
  }

  reconnect() {
    this.disconnect();
    this.connect();
  }

  close() {
    if (this.isClosed) return;
    this.disconnect(true);
    this.isClosed = true;
  }
}
