import { SockAPIErrorCode } from "sockapi/errors";
import { ScopeType } from "sockapi/scope-types";
import {
  SockAPIScopeStepPayload,
  SockAPIScopeStepResponsePayload,
} from "sockapi/scope-steps";
import { MYOCB_CONFIG } from "sockapi/scope-specs/team-myocb-spec";
import { ServerScopeHooks } from "sock-server/server-scope-specs";
import {
  ScopePermissions,
  ScopeEngineContext,
} from "sock-server/scope-engines";
import { RequestContext } from "sock-server/exec-contexts";
import { ClientConnection } from "sock-server/client-connections";
import { TeamController } from "sock-server/server-controllers/team-controller";
import { key, parse, run, validate } from "sock-server/puzzles/ignorance";
import RateLimitTracker from "sock-server/RateLimitTracker";

const GRID = [
  "..A..N..",
  "...S..W.",
  ".E.R....",
  "..F...L.",
  "O....R.A",
  "....L..T",
  "....E...",
  "...A....",
];

const gridFrom = (rows: string[]) =>
  new Set(
    rows.flatMap((row, r) =>
      [...row].flatMap((ch, c) => (ch !== "." ? [key(r, c)] : []))
    )
  );

if (
  GRID.map((row) => row.replace(/[^.]/g, "x")).join() !==
  MYOCB_CONFIG.mask.join()
)
  throw new Error("MYOCB_CONFIG.mask is out of date with GRID");

const getMYOCBResponse = (
  transcript: SockAPIScopeStepPayload<ScopeType.TEAM_MYOCB>["transcript"]
): SockAPIScopeStepResponsePayload<ScopeType.TEAM_MYOCB> => {
  const bad = validate(transcript);
  if (bad !== null) {
    return { status: "error", message: bad };
  }
  const { answer, deadAt } = run(gridFrom(GRID), transcript);
  if (deadAt !== null) {
    return { status: "warn", message: "This puzzle has a contradiction." };
  }
  if (answer.size !== 1) {
    return { status: "warn", message: "This puzzle has multiple answers." };
  }
  const [k] = [...answer];
  const { r, c } = parse(k);
  return {
    status: "ok",
    message: `Our solvers have solved your puzzle and extracted the letter ${GRID[r][c]}.`,
  };
};

class TeamMYOCBEngine {
  ctx: ScopeEngineContext<ScopeType.TEAM_MYOCB>;
  teamController: TeamController;
  checkRateLimiter: RateLimitTracker;

  constructor(
    ctx: ScopeEngineContext<ScopeType.TEAM_MYOCB>,
    teamController: TeamController
  ) {
    this.ctx = ctx;
    this.teamController = teamController;
    this.checkRateLimiter = new RateLimitTracker(
      ctx.server.clock,
      15 * 1000,
      5
    );
  }

  getPermissions(conn: ClientConnection): ScopePermissions {
    return conn.teamId === this.ctx.scope.teamId
      ? ScopePermissions.FULL
      : ScopePermissions.ADMIN_ONLY;
  }

  async handleStepAsync(
    reqCtx: RequestContext,
    payload: SockAPIScopeStepPayload<ScopeType.TEAM_MYOCB>
  ) {
    const { transcript } = payload;
    const { puzName, kinds, maxLines } = MYOCB_CONFIG;

    if (
      !reqCtx.conn.isAdmin &&
      !this.teamController.isPuzzleUnlocked(puzName)
    ) {
      return reqCtx.setPermissionDenied();
    }
    if (
      transcript.length > maxLines ||
      !transcript.every((line) => kinds.some(({ kind }) => kind === line.kind))
    ) {
      return reqCtx.setBadRequest();
    }

    if (!this.checkRateLimiter.checkRequest())
      return reqCtx.sendStepResp(this.ctx.scope, {
        status: "warn",
        message: "Too many submissions. Try again in a few seconds.",
      });
    return reqCtx.sendStepResp(this.ctx.scope, getMYOCBResponse(transcript));
  }
}

export type TeamMYOCBServerScopeSpec = {
  engine: TeamMYOCBEngine;
};

export const teamMYOCBServerScopeHooks: ServerScopeHooks<ScopeType.TEAM_MYOCB> =
  {
    createEngine: ({ execCtx, engineCtx }) => {
      const { controller, scope } = engineCtx;
      const teamController = controller.getTeamControllerIfExists(scope.teamId);
      if (teamController === null)
        return execCtx.setErrCodeAndReturn(SockAPIErrorCode.INVALID_TEAM, null);
      return new TeamMYOCBEngine(engineCtx, teamController);
    },
    engineIdentityFunc: (engine) => engine,
  };
