import { SockAPIErrorCode } from "sockapi/errors";
import { ScopeType } from "sockapi/scope-types";
import { SockAPIScopeState } from "sockapi/scope-state";
import {
  SockAPIScopeUpdatePayload,
  applyScopeUpdate,
} from "sockapi/scope-updates";
import { SockAPIScopeStepPayload } from "sockapi/scope-steps";
import {
  VOWELS_CONFIG,
  VowelsStatus,
  VowelsStatusType,
  isTeamVowelsEditable,
} from "sockapi/scope-specs/team-vowels-spec";
import { AdminQueuePuzzleSubmissionTaskSummary } from "sockapi/scope-specs/admin-queue-spec";
import {
  PuzzleSubmissionType,
  AdminQueueTaskType,
} from "sockapi/scope-specs/admin-queue-task-spec";
import { HuntNotificationType } from "sockapi/client-notifications";
import { ServerScopeHooks } from "sock-server/server-scope-specs";
import {
  ScopePermissions,
  ScopeEngineContext,
} from "sock-server/scope-engines";
import { BackendScopeState } from "sockapi/backend-scope-state";
import { RequestContext } from "sock-server/exec-contexts";
import { ClientConnection } from "sock-server/client-connections";
import { TeamController } from "sock-server/server-controllers/team-controller";

class TeamVowelsEngine {
  ctx: ScopeEngineContext<ScopeType.TEAM_VOWELS>;
  teamController: TeamController;
  state: SockAPIScopeState<ScopeType.TEAM_VOWELS>;
  adminQueueTaskId?: string;

  constructor(
    ctx: ScopeEngineContext<ScopeType.TEAM_VOWELS>,
    teamController: TeamController,
    initState?: BackendScopeState<ScopeType.TEAM_VOWELS>
  ) {
    this.ctx = ctx;
    this.teamController = teamController;
    this.state = initState ?? {};
  }

  init() {
    this.setAdminQueueTask();
  }

  getAdminQueueTask(): AdminQueuePuzzleSubmissionTaskSummary | undefined {
    const { status } = this.state;
    if (status === undefined) return undefined;
    return {
      type: AdminQueueTaskType.PUZZLE_SUBMISSION,
      submissionType: PuzzleSubmissionType.VOWELS,
      teamId: this.ctx.scope.teamId,
      requestTime: status.submitTime,
      respondTime:
        status.type === VowelsStatusType.PENDING
          ? undefined
          : status.reviewTime,
      // just make it private by default...
      isPrivate: true,
    };
  }

  setAdminQueueTask() {
    const adminQueueEngine = this.ctx.server.getAdminQueueEngine();
    const taskSummary = this.getAdminQueueTask();
    if (taskSummary === undefined) return;
    if (this.adminQueueTaskId === undefined)
      this.adminQueueTaskId = adminQueueEngine.addSubmissionTask(taskSummary);
    else adminQueueEngine.updateTask(this.adminQueueTaskId, taskSummary);
  }

  getPermissions(conn: ClientConnection): ScopePermissions {
    return conn.teamId === this.ctx.scope.teamId
      ? ScopePermissions.FULL
      : ScopePermissions.ADMIN_ONLY;
  }

  getState(): SockAPIScopeState<ScopeType.TEAM_VOWELS> {
    return this.state;
  }

  getSlowSyncState(): BackendScopeState<ScopeType.TEAM_VOWELS> {
    return this.state;
  }

  applyAndBroadcastUpdate(
    payload: SockAPIScopeUpdatePayload<ScopeType.TEAM_VOWELS>
  ) {
    applyScopeUpdate(ScopeType.TEAM_VOWELS, this.state, payload);
    this.ctx.update(this.ctx.scope, payload);
  }

  hasGuessedPrompt(): boolean {
    return [
      ...this.teamController.progressTracker.getSolveAttemptRecordsForPuzzle(
        VOWELS_CONFIG.puzName
      ),
    ].some(({ info: { message } }) => message !== undefined);
  }

  async handleAudioSubmissionAsync(url: string) {
    applyScopeUpdate(ScopeType.TEAM_VOWELS, this.state, { audioUrl: url });
    await this.ctx.fastSyncAsync(this.ctx.scope);
    // Get the latest audioUrl since it might have changed during the await.
    this.ctx.update(this.ctx.scope, { audioUrl: this.state.audioUrl });
  }

  async setStatusAsync(status: VowelsStatus) {
    const { puzName } = VOWELS_CONFIG;
    const { server, scope } = this.ctx;

    if (status.type === VowelsStatusType.ACCEPTED) {
      await this.teamController.modifyTeamProgressAsync((progressTracker) => {
        progressTracker.addSolvePuzzle(puzName);
      });
    }

    this.applyAndBroadcastUpdate({ status });

    await this.ctx.fastSyncAsync(scope);

    if (status.type === VowelsStatusType.REJECTED)
      server.broadcastNotifToTeam(scope.teamId, {
        type: HuntNotificationType.SUBMISSION_REJECTED,
        puzName,
      });

    this.setAdminQueueTask();
  }

  async handleStepAsync(
    reqCtx: RequestContext,
    payload: SockAPIScopeStepPayload<ScopeType.TEAM_VOWELS>
  ) {
    const { downloadAudioUrl, submit, review } = payload;
    const { puzName } = VOWELS_CONFIG;
    const { server, scope } = this.ctx;

    if (review !== undefined) {
      if (!reqCtx.conn.isAdmin) return reqCtx.setPermissionDenied();
      const { status } = this.state;
      if (status === undefined || status.type === VowelsStatusType.ACCEPTED)
        return reqCtx.setBadRequest();
      await this.setStatusAsync({
        ...review,
        submitTime: status.submitTime,
        reviewTime: server.clock.genTimestamp(),
      });
      return reqCtx.sendStepResp(scope, "");
    }

    if (
      !this.teamController.isPuzzleUnlocked(puzName) ||
      this.teamController.isPuzzleSolvedOrPendingSolved(puzName) ||
      !isTeamVowelsEditable(this.state) ||
      !this.hasGuessedPrompt()
    )
      return reqCtx.sendStepResp(scope, "");

    if (downloadAudioUrl ?? false) {
      await server.triggerSlowSyncDownloadAsync(true);
      return reqCtx.sendStepResp(scope, "");
    }

    if (submit ?? false) {
      if (this.state.audioUrl === undefined) return reqCtx.setBadRequest();
      await this.setStatusAsync({
        type: VowelsStatusType.PENDING,
        submitTime: server.clock.genTimestamp(),
      });
      return reqCtx.sendStepResp(scope, "");
    }

    return reqCtx.setPermissionDenied();
  }
}

export type TeamVowelsServerScopeSpec = {
  engine: TeamVowelsEngine;
};

export const teamVowelsServerScopeHooks: ServerScopeHooks<ScopeType.TEAM_VOWELS> =
  {
    createEngine: ({ execCtx, engineCtx, initState }) => {
      const { controller, scope } = engineCtx;
      const teamController = controller.getTeamControllerIfExists(scope.teamId);
      if (teamController === null)
        return execCtx.setErrCodeAndReturn(SockAPIErrorCode.INVALID_TEAM, null);
      return new TeamVowelsEngine(engineCtx, teamController, initState);
    },
    engineIdentityFunc: (engine) => engine,
  };
