import { SavedHuntBackendState } from "sockapi/scope-specs/state-download-spec";
import { SockServer } from "sock-server/SockServer";
import { MockServerInterface } from "sock-server/server-interface/MockServerInterface";
import {
  ServerInterfaceType,
  ServerInterfaceCallbacks,
} from "sock-server/server-interface/ServerInterface";
import { mockServerOpts } from "settings";
import makeMockServer from "makeMockServer";

class ResettableMockServerInterface {
  mockServerInterface: MockServerInterface;
  callbacks: ServerInterfaceCallbacks | undefined;

  constructor(sockServer: SockServer) {
    this.mockServerInterface = new MockServerInterface(sockServer);
  }

  init(callbacks: ServerInterfaceCallbacks) {
    this.callbacks = callbacks;
    this.mockServerInterface.init(callbacks);
  }

  send(msg: string) {
    this.mockServerInterface.send(msg);
  }

  reconnect() {
    this.mockServerInterface.reconnect();
  }

  close() {
    this.mockServerInterface.close();
  }

  resetServer(initState?: SavedHuntBackendState, initUnlocks?: boolean) {
    (async () => {
      this.mockServerInterface = new MockServerInterface(
        await makeMockServer(mockServerOpts, { initState, initUnlocks })
      );
      if (this.callbacks === undefined)
        throw new Error("expect callbacks to be defined");
      this.mockServerInterface.init(this.callbacks);
    })().catch(console.error);
  }
}

const makeClientMockServerInterface = async (
  type: ServerInterfaceType
): Promise<ResettableMockServerInterface> => {
  return new ResettableMockServerInterface(
    await makeMockServer(mockServerOpts)
  );
};
export default makeClientMockServerInterface;
