import { ScopeType } from "sockapi/scope-types";
import { ServerScopeHooks } from "sock-server/server-scope-specs";
import {
  ScopePermissions,
  ScopeEngineContext,
} from "sock-server/scope-engines";
import {
  PuzzleContentType,
  arePuzzleContentEqual,
} from "sockapi/scope-specs/puzzle-content-spec";
import { SockAPIScopeState } from "sockapi/scope-state";
import { ClientConnection } from "sock-server/client-connections";
import PUZZLE_CONFIG from "sock-server/puzzles/puzzle-config";

class PuzzleContentEngine {
  ctx: ScopeEngineContext<ScopeType.PUZZLE_CONTENT>;
  content: SockAPIScopeState<ScopeType.PUZZLE_CONTENT>;

  constructor(ctx: ScopeEngineContext<ScopeType.PUZZLE_CONTENT>) {
    this.ctx = ctx;
    this.content = this.makeContent();
  }

  getPermissions(conn: ClientConnection) {
    const {
      server,
      scope: { puzName },
    } = this.ctx;
    if (server.getIsHuntOver()) return ScopePermissions.READ;
    const dependentUnlock = PUZZLE_CONFIG.contentOnlyPuzzles[puzName];
    return server
      .getTeamController(conn.teamId)
      .isPuzzleUnlocked(dependentUnlock ?? puzName)
      ? ScopePermissions.READ
      : ScopePermissions.ADMIN_ONLY;
  }

  makeContent(): SockAPIScopeState<ScopeType.PUZZLE_CONTENT> {
    const {
      server,
      scope: { puzName },
    } = this.ctx;
    const { keyframesData } = server.puzzlesDB;
    const firstKeyframeId = keyframesData.firstKeyframeIds[puzName];
    if (firstKeyframeId !== undefined) {
      const { bgm = null } = server.tryGetPuzzle(puzName) ?? {};
      const keyframes = Object.fromEntries(
        Object.entries(keyframesData.keyframes).filter(
          ([, keyframe]) => keyframe.puzName === puzName
        )
      );
      return {
        type: PuzzleContentType.STORY,
        firstKeyframeId,
        bgm,
        keyframes,
      };
    } else {
      const rawContent = server.puzzlesDB.content.puzzles[puzName] ?? {
        hash: "",
        content: "",
      };
      return {
        type: PuzzleContentType.PUZZLE,
        ...rawContent,
      };
    }
  }

  getState() {
    return this.content;
  }

  updateContent(): void {
    const newContent = this.makeContent();
    if (arePuzzleContentEqual(newContent, this.content)) return;
    this.content = newContent;
    this.ctx.assign(this.ctx.scope, newContent);
  }
}

export type PuzzleContentServerScopeSpec = {
  engine: PuzzleContentEngine;
};

export const puzzleContentServerScopeHooks: ServerScopeHooks<ScopeType.PUZZLE_CONTENT> =
  {
    createEngine: ({ engineCtx }) => {
      return new PuzzleContentEngine(engineCtx);
    },
    engineIdentityFunc: (engine) => engine,
  };
