import { SockAPIErrorCode } from "sockapi/errors";
import { ScopeType } from "sockapi/scope-types";
import { SockAPIScopeState } from "sockapi/scope-state";
import { applyScopeUpdate } from "sockapi/scope-updates";
import { SockAPIScopeStepPayload } from "sockapi/scope-steps";
import {
  GRID_ADVENTURE_CONFIG,
  isValidGridAdventureCell,
} from "sockapi/scope-specs/team-grid-adventure-spec";
import { BackendScopeState } from "sockapi/backend-scope-state";
import { ServerScopeHooks } from "sock-server/server-scope-specs";
import {
  ScopePermissions,
  ScopeEngineContext,
} from "sock-server/scope-engines";
import { RequestContext } from "sock-server/exec-contexts";
import { ClientConnection } from "sock-server/client-connections";
import { TeamController } from "sock-server/server-controllers/team-controller";

class TeamGridAdventureEngine {
  ctx: ScopeEngineContext<ScopeType.TEAM_GRID_ADVENTURE>;
  teamController: TeamController;
  state: SockAPIScopeState<ScopeType.TEAM_GRID_ADVENTURE>;

  constructor(
    ctx: ScopeEngineContext<ScopeType.TEAM_GRID_ADVENTURE>,
    teamController: TeamController,
    initState?: BackendScopeState<ScopeType.TEAM_GRID_ADVENTURE>
  ) {
    this.ctx = ctx;
    this.teamController = teamController;
    this.state = initState ?? {
      cells: Array<string>(GRID_ADVENTURE_CONFIG.numCells).fill(""),
    };
  }

  getPermissions(conn: ClientConnection): ScopePermissions {
    return conn.teamId === this.ctx.scope.teamId
      ? ScopePermissions.FULL
      : ScopePermissions.ADMIN_ONLY;
  }

  getState(): SockAPIScopeState<ScopeType.TEAM_GRID_ADVENTURE> {
    return this.state;
  }

  getSlowSyncState(): BackendScopeState<ScopeType.TEAM_GRID_ADVENTURE> {
    return this.state;
  }

  async handleStepAsync(
    reqCtx: RequestContext,
    payload: SockAPIScopeStepPayload<ScopeType.TEAM_GRID_ADVENTURE>
  ) {
    const { set } = payload;
    const { puzName, numCells } = GRID_ADVENTURE_CONFIG;

    if (
      !reqCtx.conn.isAdmin &&
      !this.teamController.isPuzzleUnlocked(puzName)
    ) {
      return reqCtx.setPermissionDenied();
    }
    if (
      set.length > numCells ||
      !set.every(
        ([i, value]) =>
          Number.isInteger(i) &&
          i >= 0 &&
          i < numCells &&
          isValidGridAdventureCell(value)
      )
    ) {
      return reqCtx.setBadRequest();
    }

    applyScopeUpdate(ScopeType.TEAM_GRID_ADVENTURE, this.state, { set });
    this.ctx.update(this.ctx.scope, { set });
    return reqCtx.sendStepResp(this.ctx.scope, "");
  }
}

export type TeamGridAdventureServerScopeSpec = {
  engine: TeamGridAdventureEngine;
};

export const teamGridAdventureServerScopeHooks: ServerScopeHooks<ScopeType.TEAM_GRID_ADVENTURE> =
  {
    createEngine: ({ execCtx, engineCtx, initState }) => {
      const { controller, scope } = engineCtx;
      const teamController = controller.getTeamControllerIfExists(scope.teamId);
      if (teamController === null)
        return execCtx.setErrCodeAndReturn(SockAPIErrorCode.INVALID_TEAM, null);
      return new TeamGridAdventureEngine(engineCtx, teamController, initState);
    },
    engineIdentityFunc: (engine) => engine,
  };
