import { SockAPIErrorCode } from "sockapi/errors";
import { ScopeType } from "sockapi/scope-types";
import { SockAPIScopeState } from "sockapi/scope-state";
import { applyScopeUpdate } from "sockapi/scope-updates";
import { SockAPIScopeStepPayload } from "sockapi/scope-steps";
import { BackendScopeState } from "sockapi/backend-scope-state";
import { ServerScopeHooks } from "sock-server/server-scope-specs";
import {
  ScopePermissions,
  ScopeEngineContext,
} from "sock-server/scope-engines";
import { RequestContext } from "sock-server/exec-contexts";
import { ClientConnection } from "sock-server/client-connections";
import { TeamController } from "sock-server/server-controllers/team-controller";
import PUZZLE_CONFIG from "sock-server/puzzles/puzzle-config";
import RateLimitTracker from "sock-server/RateLimitTracker";

const { finalMetaPuzName } = PUZZLE_CONFIG;

class TeamMetametaEngine {
  ctx: ScopeEngineContext<ScopeType.TEAM_METAMETA>;
  teamController: TeamController;
  state: SockAPIScopeState<ScopeType.TEAM_METAMETA>;
  /** puzNames, grouped by day, in solution order */
  solution: string[][];
  /** puzName -> index of its day in the solution */
  solutionDay: Map<string, number>;
  /** puzNames that may also be at the start of the next day */
  pastMidnight: Set<string>;
  submitRateLimiter: RateLimitTracker;

  constructor(
    ctx: ScopeEngineContext<ScopeType.TEAM_METAMETA>,
    teamController: TeamController,
    initState?: BackendScopeState<ScopeType.TEAM_METAMETA>
  ) {
    this.ctx = ctx;
    this.teamController = teamController;
    const { server } = ctx;
    this.submitRateLimiter = new RateLimitTracker(server.clock, 30 * 1000, 5);
    const puzNameOf = new Map(
      Array.from(
        server.puzzlesDB.getPuzzles(server.customPuzzles),
        ({ puzReadable, puzName }) => [puzReadable, puzName]
      )
    );
    this.solution = PUZZLE_CONFIG.metametaSolution.map((day) =>
      day.map((puzReadable) => {
        const puzName = puzNameOf.get(puzReadable);
        if (puzName === undefined)
          throw new Error(`metametaSolution: unknown puzzle ${puzReadable}`);
        return puzName;
      })
    );
    const pastMidnight = new Set(
      PUZZLE_CONFIG.metametaPastMidnight.map((puzReadable) => {
        const puzName = puzNameOf.get(puzReadable);
        if (puzName === undefined)
          throw new Error(
            `metametaPastMidnight: unknown puzzle ${puzReadable}`
          );
        return puzName;
      })
    );
    this.solutionDay = new Map();
    this.solution.forEach((day, i) => {
      day.forEach((puzName, j) => {
        this.solutionDay.set(puzName, i);
        if (!pastMidnight.has(puzName)) return;
        const canRoll =
          i + 1 < this.solution.length &&
          day.slice(j).every((p) => pastMidnight.has(p));
        if (!canRoll)
          throw new Error(
            `metametaPastMidnight: ${puzName} must be at the end of a non-final day`
          );
      });
    });
    this.pastMidnight = pastMidnight;
    const all = this.solution.flat();
    // initially all in the first day, in unlock order
    const unlockTimes = teamController.progressTracker.view.puzzleUnlockTimes;
    const time = (puzName: string) =>
      unlockTimes[puzName] ?? Number.MAX_SAFE_INTEGER;
    const initial = all.toSorted((a, b) => time(a) - time(b));
    // reconcile if needed i guess
    const seen = new Set<string>();
    const days = this.solution.map((_, i) =>
      (initState?.days?.[i] ?? []).filter((id) => {
        if (!all.includes(id) || seen.has(id)) return false;
        seen.add(id);
        return true;
      })
    );
    days[0].push(...initial.filter((id) => !seen.has(id)));
    this.state = { days };
  }

  getPermissions(conn: ClientConnection): ScopePermissions {
    return conn.teamId === this.ctx.scope.teamId
      ? ScopePermissions.FULL
      : ScopePermissions.ADMIN_ONLY;
  }

  getState(): SockAPIScopeState<ScopeType.TEAM_METAMETA> {
    return this.state;
  }

  getSlowSyncState(): BackendScopeState<ScopeType.TEAM_METAMETA> {
    return this.state;
  }

  async handleStepAsync(
    reqCtx: RequestContext,
    payload: SockAPIScopeStepPayload<ScopeType.TEAM_METAMETA>
  ) {
    if (
      !reqCtx.conn.isAdmin &&
      !this.teamController.isPuzzleUnlocked(finalMetaPuzName)
    ) {
      return reqCtx.setPermissionDenied();
    }

    if ("submit" in payload) {
      // TODO: partials?
      if (!this.submitRateLimiter.checkRequest())
        return reqCtx.sendStepResp(this.ctx.scope, { isRateLimited: true });
      const correct =
        JSON.stringify(this.state.days.flat()) ===
          JSON.stringify(this.solution.flat()) &&
        this.state.days.every((ids, i) =>
          ids.every((id) => {
            const day = this.solutionDay.get(id);
            return day === i || (day === i - 1 && this.pastMidnight.has(id));
          })
        );
      return reqCtx.sendStepResp(this.ctx.scope, { correct });
    }

    const [id, day, beforeId] = payload.move;
    const has = (puzName: string) =>
      this.state.days.some((ids) => ids.includes(puzName));
    if (
      !has(id) ||
      !Number.isInteger(day) ||
      day < 0 ||
      day >= this.state.days.length ||
      (beforeId !== null && !has(beforeId)) ||
      id === beforeId
    ) {
      return reqCtx.setBadRequest();
    }
    applyScopeUpdate(ScopeType.TEAM_METAMETA, this.state, payload);
    this.ctx.update(this.ctx.scope, payload);
    return reqCtx.sendStepResp(this.ctx.scope, {});
  }
}

export type TeamMetametaServerScopeSpec = {
  engine: TeamMetametaEngine;
};

export const teamMetametaServerScopeHooks: ServerScopeHooks<ScopeType.TEAM_METAMETA> =
  {
    createEngine: ({ execCtx, engineCtx, initState }) => {
      const { controller, scope } = engineCtx;
      const teamController = controller.getTeamControllerIfExists(scope.teamId);
      if (teamController === null)
        return execCtx.setErrCodeAndReturn(SockAPIErrorCode.INVALID_TEAM, null);
      return new TeamMetametaEngine(engineCtx, teamController, initState);
    },
    engineIdentityFunc: (engine) => engine,
  };
