import { SockAPIErrorCode } from "sockapi/errors";
import { ScopeType } from "sockapi/scope-types";
import { SockAPIScopeState } from "sockapi/scope-state";
import { applyScopeUpdate } from "sockapi/scope-updates";
import { SockAPIScopeStepPayload } from "sockapi/scope-steps";
import {
  WORDTRIS_CONFIG,
  WordtrisPlacement,
  isValidWordtrisLetter,
} from "sockapi/scope-specs/team-wordtris-spec";
import { BackendScopeState } from "sockapi/backend-scope-state";
import { ServerScopeHooks } from "sock-server/server-scope-specs";
import {
  ScopePermissions,
  ScopeEngineContext,
} from "sock-server/scope-engines";
import { RequestContext } from "sock-server/exec-contexts";
import { ClientConnection } from "sock-server/client-connections";
import { TeamController } from "sock-server/server-controllers/team-controller";

class TeamWordtrisEngine {
  ctx: ScopeEngineContext<ScopeType.TEAM_WORDTRIS>;
  teamController: TeamController;
  state: SockAPIScopeState<ScopeType.TEAM_WORDTRIS>;

  constructor(
    ctx: ScopeEngineContext<ScopeType.TEAM_WORDTRIS>,
    teamController: TeamController,
    initState?: BackendScopeState<ScopeType.TEAM_WORDTRIS>
  ) {
    this.ctx = ctx;
    this.teamController = teamController;
    const { numPieces, cellsPerPiece } = WORDTRIS_CONFIG;
    this.state = initState ?? {
      letters: Array<string>(numPieces * cellsPerPiece).fill(""),
      placements: Array<WordtrisPlacement | null>(numPieces).fill(null),
    };
  }

  getPermissions(conn: ClientConnection): ScopePermissions {
    return conn.teamId === this.ctx.scope.teamId
      ? ScopePermissions.FULL
      : ScopePermissions.ADMIN_ONLY;
  }

  getState(): SockAPIScopeState<ScopeType.TEAM_WORDTRIS> {
    return this.state;
  }

  getSlowSyncState(): BackendScopeState<ScopeType.TEAM_WORDTRIS> {
    return this.state;
  }

  async handleStepAsync(
    reqCtx: RequestContext,
    payload: SockAPIScopeStepPayload<ScopeType.TEAM_WORDTRIS>
  ) {
    const { letters = [], place = [] } = payload;
    const { puzName, numPieces, cellsPerPiece, numGrids, rows, cols } =
      WORDTRIS_CONFIG;
    const isIndex = (i: number, n: number) =>
      Number.isInteger(i) && i >= 0 && i < n;

    if (
      !reqCtx.conn.isAdmin &&
      !this.teamController.isPuzzleUnlocked(puzName)
    ) {
      return reqCtx.setPermissionDenied();
    }
    // only the bounding box's corner is checked, not the whole
    // piece, since piece shapes live in the MDX; the client keeps pieces in.
    if (
      letters.length > numPieces * cellsPerPiece ||
      place.length > numPieces ||
      !letters.every(
        ([i, value]) =>
          isIndex(i, numPieces * cellsPerPiece) && isValidWordtrisLetter(value)
      ) ||
      !place.every(
        ([p, placement]) =>
          isIndex(p, numPieces) &&
          (placement === null ||
            (isIndex(placement.grid, numGrids) &&
              isIndex(placement.row, rows) &&
              isIndex(placement.col, cols)))
      )
    ) {
      return reqCtx.setBadRequest();
    }

    // Store only the fields we know, not whatever else the client sent.
    const update = {
      letters,
      place: place.map(([p, pl]): [number, WordtrisPlacement | null] => [
        p,
        pl && { grid: pl.grid, row: pl.row, col: pl.col, rot: pl.rot },
      ]),
    };
    applyScopeUpdate(ScopeType.TEAM_WORDTRIS, this.state, update);
    this.ctx.update(this.ctx.scope, update);
    return reqCtx.sendStepResp(this.ctx.scope, "");
  }
}

export type TeamWordtrisServerScopeSpec = {
  engine: TeamWordtrisEngine;
};

export const teamWordtrisServerScopeHooks: ServerScopeHooks<ScopeType.TEAM_WORDTRIS> =
  {
    createEngine: ({ execCtx, engineCtx, initState }) => {
      const { controller, scope } = engineCtx;
      const teamController = controller.getTeamControllerIfExists(scope.teamId);
      if (teamController === null)
        return execCtx.setErrCodeAndReturn(SockAPIErrorCode.INVALID_TEAM, null);
      return new TeamWordtrisEngine(engineCtx, teamController, initState);
    },
    engineIdentityFunc: (engine) => engine,
  };
