import { ScopeType } from "sockapi/scope-types";
import { SockAPIScopeState } from "sockapi/scope-state";
import {
  SolveDialogueEntry,
  SolveDialogueLine,
  solveDialogueSpriteName,
} from "sockapi/scope-specs/solve-dialogue-spec";
import { ServerScopeHooks } from "sock-server/server-scope-specs";
import {
  ScopePermissions,
  ScopeEngineContext,
} from "sock-server/scope-engines";
import { ClientConnection } from "sock-server/client-connections";
import CUTSCENE_CHARACTERS from "sock-server/puzzles/cutscene-characters";
import { PuzzlesDB } from "sock-server/puzzles/PuzzlesDB";
import { PuzzleType } from "sockapi/puzzle-data";

/** Fill in the speaker's name, color, and sprite from the character list. */
const resolveLine = (entry: SolveDialogueEntry): SolveDialogueLine => {
  const { characterId, sprite } = entry;
  // Unknown character -> use their id as the name
  const character = CUTSCENE_CHARACTERS[characterId];
  return {
    ...entry,
    name: character?.name ?? characterId,
    color: character?.color,
    imageName:
      sprite === undefined ? undefined : solveDialogueSpriteName(sprite),
  };
};

/** The cutscene that solving `puzName` unlocks, if any (e.g. a meta's postmeta). */
const solveCutscene = (
  puzzlesDB: PuzzlesDB,
  puzName: string
): { puzName: string; slug: string } | undefined => {
  for (const puzData of puzzlesDB.getPuzzles({})) {
    if (puzData.type !== PuzzleType.STORY) continue;
    if (
      puzData.unlockInEdges.some(
        ({ unlockGroupId }) => unlockGroupId === `solve__${puzName}`
      )
    )
      return { puzName: puzData.puzName, slug: puzData.slug };
  }
  return undefined;
};

/** The dialogue for one puzzle, only readable once the team has solved it. */
class SolveDialogueEngine {
  ctx: ScopeEngineContext<ScopeType.SOLVE_DIALOGUE>;

  constructor(ctx: ScopeEngineContext<ScopeType.SOLVE_DIALOGUE>) {
    this.ctx = ctx;
  }

  getPermissions(conn: ClientConnection): ScopePermissions {
    const {
      server,
      scope: { puzName },
    } = this.ctx;
    // After the hunt, everyone can read it. Before then, only teams who solved it
    if (server.getIsHuntOver()) return ScopePermissions.READ;
    return server.getTeamController(conn.teamId).isPuzzleSolved(puzName)
      ? ScopePermissions.READ
      : ScopePermissions.ADMIN_ONLY;
  }

  getState(): SockAPIScopeState<ScopeType.SOLVE_DIALOGUE> {
    const {
      server,
      scope: { puzName },
    } = this.ctx;
    // Puzzle has no dialogue -> no lines
    const entries = server.puzzlesDB.solveDialogueData[puzName] ?? [];
    const cutscene = solveCutscene(server.puzzlesDB, puzName);
    return {
      lines: entries.map(resolveLine),
      ...(cutscene === undefined ? {} : { cutscene }),
    };
  }
}

export type SolveDialogueServerScopeSpec = {
  engine: SolveDialogueEngine;
};

export const solveDialogueServerScopeHooks: ServerScopeHooks<ScopeType.SOLVE_DIALOGUE> =
  {
    createEngine: ({ engineCtx }) => new SolveDialogueEngine(engineCtx),
    engineIdentityFunc: (engine) => engine,
  };
